content:
:root {
  --primary-color: #0d9488;
  --primary-hover: #0f766e;
  --primary-light: #ccfbf1;
  --bg-gradient-start: #f0fdfa;
  --bg-gradient-end: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --text-light: #94a3b8;
  --border-color: #e2e8f0;
  --border-focus: #14b8a6;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 20px;
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.05), 0 1px 2px rgba(0, 0, 0, 0.03);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --transition-fast: 0.15s ease;
  --transition-normal: 0.25s ease;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, 'Hiragino Sans', 'Hiragino Kaku Gothic ProN', Meiryo, sans-serif;
  color: var(--text-main);
  background: linear-gradient(135deg, var(--bg-gradient-start) 0%, var(--bg-gradient-end) 100%);
  min-height: 100vh;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* アプリ全体レイアウト */
.app-container {
  max-width: 760px;
  margin: 0 auto;
  padding: 2rem 1.25rem 3.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.75rem;
}

/* ヘッダー */
.header {
  text-align: center;
  padding: 0.5rem 0;
}

.header-title {
  font-size: 1.875rem;
  font-weight: 800;
  color: #115e59;
  letter-spacing: -0.025em;
  margin-bottom: 0.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
}

.header-subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
  font-weight: 500;
}

/* 入力カード */
.calculator-card {
  background: var(--card-bg);
  border-radius: var(--radius-xl);
  padding: 1.75rem;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.input-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
}

@media (max-width: 600px) {
  .input-grid {
    grid-template-columns: 1fr;
    gap: 1.25rem;
  }
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.input-label {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.input-wrapper {
  position: relative;
  display: flex;
  align-items: center;
}

.number-input {
  width: 100%;
  padding: 0.65rem 3rem 0.65rem 0.9rem;
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--text-main);
  background-color: #f8fafc;
  border: 2px solid var(--border-color);
  border-radius: var(--radius-md);
  outline: none;
  transition: border-color var(--transition-fast), background-color var(--transition-fast), box-shadow var(--transition-fast);
  -moz-appearance: textfield;
}

.number-input::-webkit-outer-spin-button,
.number-input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.number-input:focus {
  background-color: #ffffff;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(20, 184, 166, 0.2);
}

.unit-badge {
  position: absolute;
  right: 0.9rem;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
  pointer-events: none;
}

.range-slider {
  width: 100%;
  height: 6px;
  -webkit-appearance: none;
  appearance: none;
  background: #e2e8f0;
  border-radius: 999px;
  outline: none;
  margin-top: 0.25rem;
  cursor: pointer;
}

.range-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--primary-color);
  border: 2px solid #ffffff;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.25);
  cursor: grab;
  transition: transform var(--transition-fast), background-color var(--transition-fast);
}

.range-slider::-webkit-slider-thumb:hover {
  transform: scale(1.15);
  background: var(--primary-hover);
}

.range-slider::-webkit-slider-thumb:active {
  cursor: grabbing;
  transform: scale(1.1);
}

.range-slider::-moz-range-thumb {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--primary-color);
  border: 2px solid #ffffff;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.25);
  cursor: grab;
  transition: transform var(--transition-fast), background-color var(--transition-fast);
}

.range-slider::-moz-range-thumb:hover {
  transform: scale(1.15);
  background: var(--primary-hover);
}

.range-slider::-moz-range-thumb:active {
  cursor: grabbing;
  transform: scale(1.1);
}

/* プリセット選択ボタン */
.quick-presets {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: center;
  padding-top: 0.5rem;
  border-top: 1px dashed var(--border-color);
}

.preset-btn {
  background: #f1f5f9;
  border: 1px solid #e2e8f0;
  color: var(--text-muted);
  padding: 0.35rem 0.75rem;
  border-radius: 9999px;
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color var(--transition-fast), color var(--transition-fast), border-color var(--transition-fast);
}

.preset-btn:hover {
  background: var(--primary-light);
  color: #0f766e;
  border-color: #99f6e4;
}

/* 結果表示カード */
.result-card {
  background: var(--card-bg);
  border-radius: var(--radius-xl);
  padding: 1.75rem;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.result-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  flex-wrap: wrap;
  gap: 1rem;
}

.result-bmi-val {
  font-size: 3.25rem;
  font-weight: 800;
  line-height: 1;
  color: var(--text-main);
  letter-spacing: -0.03em;
}

.result-bmi-unit {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-muted);
  margin-left: 0.35rem;
}

.result-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1.1rem;
  border-radius: 9999px;
  font-size: 1.05rem;
  font-weight: 700;
  color: #ffffff;
  box-shadow: var(--shadow-sm);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.15);
}

/* 適正体重ボックス */
.ideal-weight-box {
  background: #f8fafc;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.1rem 1.25rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.ideal-weight-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.ideal-weight-value {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--text-main);
}

/* BMIカラーメーター */
.meter-container {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  padding: 1rem 0 0.5rem;
}

.meter-bar {
  position: relative;
  width: 100%;
  height: 16px;
  border-radius: 999px;
  overflow: visible;
  display: flex;
  background: #e2e8f0;
}

.meter-segment {
  height: 100%;
  position: relative;
  transition: opacity var(--transition-fast);
}

.meter-segment:first-child {
  border-top-left-radius: 999px;
  border-bottom-left-radius: 999px;
}

.meter-segment:last-child {
  border-top-right-radius: 999px;
  border-bottom-right-radius: 999px;
}

.meter-indicator {
  position: absolute;
  top: -12px;
  transform: translateX(-50%);
  width: 0;
  height: 0;
  border-left: 8px solid transparent;
  border-right: 8px solid transparent;
  border-top: 10px solid #0f172a;
  transition: left var(--transition-normal);
  filter: drop-shadow(0 2px 2px rgba(0, 0, 0, 0.3));
  z-index: 10;
  pointer-events: none;
}

.meter-labels {
  display: flex;
  justify-content: space-between;
  width: 100%;
  padding: 0 2px;
}

.meter-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-light);
}

/* 日本肥満学会 判定基準表 */
.category-table-card {
  background: var(--card-bg);
  border-radius: var(--radius-xl);
  padding: 1.75rem;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--border-color);
}

.table-title {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.category-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 0.9rem;
}

.category-table th {
  background-color: #f8fafc;
  color: var(--text-muted);
  font-weight: 700;
  text-align: left;
  padding: 0.75rem 1rem;
  border-bottom: 2px solid var(--border-color);
}

.category-table th:first-child {
  border-top-left-radius: var(--radius-sm);
}

.category-table th:last-child {
  border-top-right-radius: var(--radius-sm);
}

.table-row {
  transition: background-color var(--transition-fast);
  border-bottom: 1px solid #f1f5f9;
}

.table-row:hover {
  background-color: #f8fafc;
}

.table-row-active {
  background-color: #f0fdfa !important;
  font-weight: 700;
}

.table-cell {
  padding: 0.75rem 1rem;
  border-bottom: 1px solid #f1f5f9;
  vertical-align: middle;
}

.color-dot {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  margin-right: 0.5rem;
  vertical-align: middle;
}

/* 注釈・フッター */
.footer-note {
  text-align: center;
  font-size: 0.8rem;
  color: var(--text-light);
  line-height: 1.6;
}

export type BmiCategoryType = 'underweight' | 'normal' | 'obese1' | 'obese2' | 'obese3' | 'obese4';

export interface BmiCategoryInfo {
  id: BmiCategoryType;
  label: string;
  minBmi: number;
  maxBmi: number;
  color: string;
  description: string;
}

export interface BmiCalculationResult {
  bmi: number;
  category: BmiCategoryInfo;
  idealWeight: number;
  weightDiff: number;
}

export interface BmiMeterProps {
  bmi: number;
  categories: BmiCategoryInfo[];
}

import { BmiCategoryInfo, BmiCalculationResult } from '../types';

export const BMI_CATEGORIES: BmiCategoryInfo[] = [
  {
    id: 'underweight',
    label: '低体重 (痩せ型)',
    minBmi: 0,
    maxBmi: 18.5,
    color: '#38bdf8',
    description: '18.5未満：栄養不足や体調不良に注意が必要です'
  },
  {
    id: 'normal',
    label: '普通体重',
    minBmi: 18.5,
    maxBmi: 25.0,
    color: '#10b981',
    description: '18.5以上〜25未満：最も疾病率が低い理想的な範囲です'
  },
  {
    id: 'obese1',
    label: '肥満 (1度)',
    minBmi: 25.0,
    maxBmi: 30.0,
    color: '#f59e0b',
    description: '25以上〜30未満：生活習慣病への予防・対策を意識しましょう'
  },
  {
    id: 'obese2',
    label: '肥満 (2度)',
    minBmi: 30.0,
    maxBmi: 35.0,
    color: '#f97316',
    description: '30以上〜35未満：積極的な体重管理と食生活の見直しが推奨されます'
  },
  {
    id: 'obese3',
    label: '肥満 (3度)',
    minBmi: 35.0,
    maxBmi: 40.0,
    color: '#ef4444',
    description: '35以上〜40未満：高度肥満とされ、専門医への相談が望ましいです'
  },
  {
    id: 'obese4',
    label: '肥満 (4度)',
    minBmi: 40.0,
    maxBmi: 100,
    color: '#991b1b',
    description: '40以上：重大な健康リスクが生じる可能性が高いため医療指導が必要です'
  }
];

export const calculateBmi = (heightCm: number, weightKg: number): BmiCalculationResult => {
  const safeHeightCm = Math.max(heightCm, 1);
  const safeWeightKg = Math.max(weightKg, 0);

  const heightM = safeHeightCm / 100;
  const rawBmi = safeWeightKg / (heightM * heightM);
  const bmi = Math.round(rawBmi * 10) / 10;

  // 適正体重 (BMI 22 基準)
  const rawIdealWeight = 22 * heightM * heightM;
  const idealWeight = Math.round(rawIdealWeight * 10) / 10;

  // 適正体重との差分
  const weightDiff = Math.round((safeWeightKg - idealWeight) * 10) / 10;

  // 日本肥満学会基準に基づく判定
  const matchedCategory = BMI_CATEGORIES.find((cat) => {
    if (cat.id === 'underweight') {
      return bmi < cat.maxBmi;
    }
    if (cat.id === 'obese4') {
      return bmi >= cat.minBmi;
    }
    return bmi >= cat.minBmi && bmi < cat.maxBmi;
  });

  const category = matchedCategory || BMI_CATEGORIES[BMI_CATEGORIES.length - 1];

  return {
    bmi,
    category,
    idealWeight,
    weightDiff
  };
};

import { BmiMeterProps } from '../types';

const METER_MIN_BMI = 15;
const METER_MAX_BMI = 40;

const BmiMeter = ({ bmi, categories = [] }: BmiMeterProps) => {
  // BMIをメーター表示範囲 (15〜40) に正規化
  const clampedBmi = Math.min(Math.max(bmi, METER_MIN_BMI), METER_MAX_BMI);
  const indicatorPosition = ((clampedBmi - METER_MIN_BMI) / (METER_MAX_BMI - METER_MIN_BMI)) * 100;

  // メーターセグメントの基準比率 (合計 25 幅 = 15〜40)
  // 低体重 (15〜18.5 = 3.5幅 -> 14%)
  // 普通体重 (18.5〜25 = 6.5幅 -> 26%)
  // 肥満1度 (25〜30 = 5幅 -> 20%)
  // 肥満2度 (30〜35 = 5幅 -> 20%)
  // 肥満3度以上 (35〜40+ = 5幅 -> 20%)
  const segmentWidths: Record<string, number> = {
    underweight: 14,
    normal: 26,
    obese1: 20,
    obese2: 20,
    obese3: 10,
    obese4: 10
  };

  return (
    <div className="meter-container">
      <div className="meter-bar">
        <div
          className="meter-indicator"
          style={{ left: `${indicatorPosition}%` }}
          aria-hidden="true"
        />
        {categories.map((cat) => {
          const width = segmentWidths[cat.id] ?? 16.6;
          return (
            <div
              key={cat.id}
              className="meter-segment"
              style={{
                width: `${width}%`,
                backgroundColor: cat.color
              }}
              title={`${cat.label}: ${cat.minBmi}〜${cat.maxBmi === 100 ? '40以上' : cat.maxBmi}`}
            />
          );
        })}
      </div>
      <div className="meter-labels">
        <span className="meter-label">15</span>
        <span className="meter-label">18.5</span>
        <span className="meter-label">25</span>
        <span className="meter-label">30</span>
        <span className="meter-label">35</span>
        <span className="meter-label">40+</span>
      </div>
    </div>
  );
};

export default BmiMeter;

import { useState, useMemo, ChangeEvent } from 'react';
import { Calculator, Scale, HeartPulse, CheckCircle2, AlertCircle } from 'lucide-react';
import { calculateBmi, BMI_CATEGORIES } from './utils/bmiCalculator';
import BmiMeter from './components/BmiMeter';

interface PresetItem {
  label: string;
  height: number;
  weight: number;
}

const PRESETS: PresetItem[] = [
  { label: '成人男性の標準', height: 171, weight: 66 },
  { label: '成人女性の標準', height: 158, weight: 53 },
  { label: 'スリム体型', height: 165, weight: 49 },
  { label: '筋肉質・がっしり', height: 178, weight: 79 }
];

const App = () => {
  const [height, setHeight] = useState<number>(170);
  const [weight, setWeight] = useState<number>(65);

  const result = useMemo(() => {
    return calculateBmi(height, weight);
  }, [height, weight]);

  const handleHeightNumberChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    if (!isNaN(val)) {
      setHeight(Math.max(50, Math.min(250, val)));
    } else {
      setHeight(0);
    }
  };

  const handleWeightNumberChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    if (!isNaN(val)) {
      setWeight(Math.max(10, Math.min(300, val)));
    } else {
      setWeight(0);
    }
  };

  const handleHeightSliderChange = (e: ChangeEvent<HTMLInputElement>) => {
    setHeight(parseFloat(e.target.value));
  };

  const handleWeightSliderChange = (e: ChangeEvent<HTMLInputElement>) => {
    setWeight(parseFloat(e.target.value));
  };

  const applyPreset = (preset: PresetItem) => {
    setHeight(preset.height);
    setWeight(preset.weight);
  };

  const diffText = useMemo(() => {
    if (result.weightDiff === 0) {
      return '適正体重とちょうど同じです';
    }
    const diffAbs = Math.abs(result.weightDiff).toFixed(1);
    if (result.weightDiff > 0) {
      return `適正体重より +${diffAbs} kg`;
    }
    return `適正体重より -${diffAbs} kg`;
  }, [result.weightDiff]);

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="header-title">
          <Calculator size={32} />
          BMI計算ツール
        </h1>
        <p className="header-subtitle">
          身長・体重から肥満度・適正体重（BMI 22）を即座にチェック
        </p>
      </header>

      {/* 入力フォームカード */}
      <section className="calculator-card" aria-label="身長と体重の入力">
        <div className="input-grid">
          {/* 身長入力 */}
          <div className="input-group">
            <label htmlFor="height-input" className="input-label">
              <span>身長 (cm)</span>
              <span style={{ color: '#0d9488', fontWeight: 800 }}>{height} cm</span>
            </label>
            <div className="input-wrapper">
              <input
                id="height-input"
                type="number"
                className="number-input"
                value={height === 0 ? '' : height}
                onChange={handleHeightNumberChange}
                min={100}
                max={230}
                step={0.5}
              />
              <span className="unit-badge">cm</span>
            </div>
            <input
              type="range"
              className="range-slider"
              value={height}
              onChange={handleHeightSliderChange}
              min={120}
              max={210}
              step={0.5}
              aria-label="身長スライダー"
            />
          </div>

          {/* 体重入力 */}
          <div className="input-group">
            <label htmlFor="weight-input" className="input-label">
              <span>体重 (kg)</span>
              <span style={{ color: '#0d9488', fontWeight: 800 }}>{weight} kg</span>
            </label>
            <div className="input-wrapper">
              <input
                id="weight-input"
                type="number"
                className="number-input"
                value={weight === 0 ? '' : weight}
                onChange={handleWeightNumberChange}
                min={20}
                max={200}
                step={0.5}
              />
              <span className="unit-badge">kg</span>
            </div>
            <input
              type="range"
              className="range-slider"
              value={weight}
              onChange={handleWeightSliderChange}
              min={30}
              max={140}
              step={0.5}
              aria-label="体重スライダー"
            />
          </div>
        </div>

        {/* クイックプリセット */}
        <div className="quick-presets">
          <span style={{ fontSize: '0.8rem', fontWeight: 700, color: '#64748b' }}>
            クイック入力:
          </span>
          {PRESETS.map((preset) => (
            <button
              key={preset.label}
              type="button"
              className="preset-btn"
              onClick={() => applyPreset(preset)}
            >
              {preset.label} ({preset.height}cm / {preset.weight}kg)
            </button>
          ))}
        </div>
      </section>

      {/* 判定結果カード */}
      <section className="result-card" aria-label="計算結果">
        <div className="result-header">
          <div>
            <div style={{ fontSize: '0.9rem', fontWeight: 700, color: '#64748b', marginBottom: '0.25rem' }}>
              あなたのBMI指数
            </div>
            <div style={{ display: 'flex', alignItems: 'baseline' }}>
              <span className="result-bmi-val">{result.bmi.toFixed(1)}</span>
              <span className="result-bmi-unit">BMI</span>
            </div>
          </div>

          <div
            className="result-badge"
            style={{ backgroundColor: result.category.color }}
          >
            {result.category.id === 'normal' ? (
              <CheckCircle2 size={20} />
            ) : (
              <AlertCircle size={20} />
            )}
            <span>{result.category.label}</span>
          </div>
        </div>

        {/* 視覚的カラーメーター */}
        <BmiMeter bmi={result.bmi} categories={BMI_CATEGORIES} />

        {/* 適正体重ボックス */}
        <div className="ideal-weight-box">
          <div>
            <div className="ideal-weight-title">
              <Scale size={18} />
              <span>適正体重 (BMI 22基準)</span>
            </div>
            <div style={{ fontSize: '0.85rem', color: '#64748b', marginTop: '0.2rem' }}>
              {diffText}
            </div>
          </div>
          <div className="ideal-weight-value">
            {result.idealWeight.toFixed(1)} <span style={{ fontSize: '0.9rem', fontWeight: 600 }}>kg</span>
          </div>
        </div>
      </section>

      {/* 日本肥満学会 判定基準表 */}
      <section className="category-table-card" aria-label="日本肥満学会 判定基準表">
        <h2 className="table-title">
          <HeartPulse size={20} color="#0d9488" />
          日本肥満学会の判定基準一覧
        </h2>
        <table className="category-table">
          <thead>
            <tr>
              <th>判定区分</th>
              <th>BMI範囲</th>
              <th>健康への目安・アドバイス</th>
            </tr>
          </thead>
          <tbody>
            {BMI_CATEGORIES.map((cat) => {
              const isActive = cat.id === result.category.id;
              let rangeText = '';
              if (cat.minBmi === 0) {
                rangeText = `${cat.maxBmi} 未満`;
              } else if (cat.maxBmi === 100) {
                rangeText = `${cat.minBmi} 以上`;
              } else {
                rangeText = `${cat.minBmi} 以上 〜 ${cat.maxBmi} 未満`;
              }

              return (
                <tr
                  key={cat.id}
                  className={isActive ? 'table-row table-row-active' : 'table-row'}
                >
                  <td className="table-cell">
                    <span
                      className="color-dot"
                      style={{ backgroundColor: cat.color }}
                    />
                    {cat.label}
                    {isActive && (
                      <span
                        style={{
                          marginLeft: '0.5rem',
                          fontSize: '0.75rem',
                          color: '#0d9488',
                          fontWeight: 800
                        }}
                      >
                        【現在】
                      </span>
                    )}
                  </td>
                  <td className="table-cell" style={{ whiteSpace: 'nowrap' }}>
                    {rangeText}
                  </td>
                  <td className="table-cell" style={{ color: isActive ? '#0f172a' : '#64748b' }}>
                    {cat.description}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </section>

      <footer className="footer-note">
        ※ BMI（Body Mass Index）は体重と身長から算出される肥満度を表す国際的な体格指数です。<br />
        筋肉量や骨密度、体脂肪率などは考慮されないため、あくまで健康管理のひとつの目安としてご活用ください。
      </footer>
    </div>
  );
};

export default App;
